function stopCamera(){
  cameraGeneration++;clearTimeout(scanTimer);camera?.getTracks().forEach(track=>track.stop());camera=null;
  document.querySelector('#scanner-shell')?.classList.remove('is-scanning');
  const video=document.querySelector('#video');if(video){video.pause();video.srcObject=null;video.hidden=true;}
  const scan=document.querySelector('#scan');if(scan){scan.disabled=false;scan.textContent='Abrir cámara';}
  const stop=document.querySelector('#stop-scan');if(stop)stop.hidden=true;
}
