function stopCardSync(){clearTimeout(syncTimer);syncGeneration++;}
function canSyncCard(){return user?.role==='customer'&&!user.mustChangeSecret&&location.hash==='#tarjeta'&&!document.hidden&&Boolean(document.querySelector('#qr'));}
function scheduleCardSync(delay=5000){clearTimeout(syncTimer);if(canSyncCard())syncTimer=setTimeout(syncCustomerCard,delay);}
async function syncCustomerCard(){
  if(!canSyncCard()||stampStyleBusy)return;
  if(syncBusy){scheduleCardSync();return;}
  const generation=syncGeneration,customerId=user.id;
  syncBusy=true;let nextDelay=5000;
  try{
    const {card}=await api('/api/card',{signal:AbortSignal.timeout(10000)});
    if(generation!==syncGeneration||!canSyncCard()||user.id!==customerId||stampStyleBusy)return;
    const previous=currentCard;
    if(JSON.stringify(previous)!==JSON.stringify(card)&&!document.querySelector('#download-card:disabled')){
      currentCard=card;
      app.innerHTML=customerView();
      const qr=qrcode(0,'M');qr.addData(card.qrValue);qr.make();
      document.querySelector('#qr').innerHTML=qr.createSvgTag({cellSize:4,margin:16,scalable:true});
      bind('tarjeta');
      app.querySelector('.card')?.classList.add('card-updated');
      if(card.stamps>previous.stamps){const added=card.stamps-previous.stamps;toast(card.stamps>=card.goal?'¡Tu café gratis está listo!':added===1?'¡Un nuevo sello para tu próximo café!':`¡${added} sellos nuevos para tu próximo café!`);}
      else if(card.redeemed>previous.redeemed)toast('Café canjeado. Empieza un nuevo recorrido.');
      else if(card.stamps!==previous.stamps)toast('El mostrador actualizó tus sellos.');
    }
    const status=document.querySelector('#sync-status');if(status){status.classList.remove('is-offline');status.innerHTML='<i aria-hidden="true"></i>Tarjeta al día · Actualización automática';}
  }catch(error){
    if(generation!==syncGeneration||!canSyncCard())return;
    if(error.status===401){user=null;location.hash='login';return;}
    if(error.code==='secret_change_required'){user.mustChangeSecret=true;location.hash='cuenta';return;}
    nextDelay=15000;
    const status=document.querySelector('#sync-status');if(status){status.classList.add('is-offline');status.textContent='Esperando conexión · Reintentaremos automáticamente';}
  }finally{syncBusy=false;if(generation===syncGeneration)scheduleCardSync(nextDelay);}
}
async function adjustStamps(id){
  const customer=adminData.customers.find(item=>item.customer_id===id);if(!customer)return;
  const dialog=document.createElement('dialog');dialog.className='adjust-dialog';
  const daily=adminData.business.stamp_policy!=='per_item';dialog.innerHTML=`<form id="adjust-form"><p class="eyebrow">AJUSTE ADMINISTRATIVO</p><h2>Un detalle por corregir.</h2><p><strong>${dataText(customer.name)}</strong><br>${customer.stamps} / ${adminData.business.reward_goal} sellos actuales</p><label>Movimiento<select name="delta"><option value="1" ${customer.stamps>=adminData.business.reward_goal?'disabled':''}>Añadir un sello</option><option value="-1" ${customer.stamps===0?'disabled':''}>Quitar un sello</option></select></label><label>Motivo<textarea name="reason" minlength="5" maxlength="200" rows="3" required placeholder="Ej. Compra cancelada o sello omitido"></textarea></label><label class="check-label" id="cancel-visit-label" hidden><input type="checkbox" name="cancelToday">Anular también el sello de hoy para permitir una nueva visita hoy.</label><p class="note">El ajuste quedará registrado con tu usuario, fecha y motivo.${daily?' Añadir un sello manual no cuenta como la visita diaria.':''}</p><p class="error" role="alert"></p><div class="actions"><button type="button" class="secondary" id="cancel-adjust">Cancelar</button><button type="submit">Confirmar ajuste</button></div></form>`;
  document.body.append(dialog);dialog.showModal();
  const form=dialog.querySelector('form'),select=form.elements.delta;
  if(customer.stamps>=adminData.business.reward_goal)select.value='-1';
  const hasToday=customer.last_stamp_at&&new Intl.DateTimeFormat('en-CA',{timeZone:tenant.timezone}).format(new Date(customer.last_stamp_at))===new Intl.DateTimeFormat('en-CA',{timeZone:tenant.timezone}).format(new Date());
  const toggle=()=>{dialog.querySelector('#cancel-visit-label').hidden=!daily||select.value!=='-1'||!hasToday;if(select.value!=='-1'||!daily)form.elements.cancelToday.checked=false;};
  select.onchange=toggle;toggle();
  dialog.querySelector('#cancel-adjust').onclick=()=>dialog.close();
  dialog.addEventListener('close',()=>dialog.remove(),{once:true});
  form.onsubmit=async event=>{
    event.preventDefault();const submit=form.querySelector('[type="submit"]');submit.disabled=true;
    try{
      await api(`/api/admin/customers/${id}/stamps`,{method:'POST',body:JSON.stringify({delta:Number(select.value),expectedStamps:customer.stamps,reason:form.elements.reason.value.trim(),cancelToday:form.elements.cancelToday.checked})});
      dialog.close();toast('Sellos actualizados. El cliente verá el cambio automáticamente.');await render();
    }catch(error){form.querySelector('.error').textContent=error.message;submit.disabled=false;}
  };
}

