async function findCard(value){try{selectedCard=(await api(`/api/staff/card?value=${encodeURIComponent(value)}`)).card;stampQuantity=1;await render();}catch(error){toast(error.message);}}
async function move(type){if(!selectedCard||moving)return;const perItem=selectedCard.stampPolicy==='per_item',quantity=perItem?stampQuantity:1,outcome=perItem?purchaseOutcome(selectedCard,quantity):null;const question=type==='stamp'?(perItem?`${purchaseSummaryText(outcome)}\n\n¿Confirmar para ${selectedCard.name}?`:`¿Registrar el sello de hoy para ${selectedCard.name}?`):`¿Canjear ${selectedCard.reward.toLowerCase()} de ${selectedCard.name}?`;if(!ask(question))return;moving=true;document.querySelectorAll('#stamp,#redeem,#stamp-minus,#stamp-plus').forEach(button=>button.disabled=true);try{const result=await api(`/api/staff/${type}`,{method:'POST',body:JSON.stringify({cardId:selectedCard.id,...(type==='stamp'?{quantity}:{})})});selectedCard=result.card;stampQuantity=1;await render();toast(type==='stamp'?(result.operation?.freeCoffees?`Pedido registrado: ${result.operation.freeCoffees} café gratis aplicado.`:quantity===1?'Sello registrado.':`${quantity} sellos registrados.`):'Café canjeado.');}catch(error){toast(error.message);await findCard(selectedCard.id);}finally{moving=false;}}
async function startCamera(){
stopCamera();const generation=cameraGeneration,button=document.querySelector('#scan');if(button){button.disabled=true;button.textContent='Abriendo cámara…';}
if(!navigator.mediaDevices?.getUserMedia){stopCamera();toast('Este navegador no permite abrir la cámara. Busca por tarjeta o celular.');return;}
try{
let detector=null;
if('BarcodeDetector'in window){try{detector=new BarcodeDetector({formats:['qr_code']});}catch{detector=null;}}
if(!detector&&typeof window.jsQR!=='function'){stopCamera();toast('Este navegador no permite escanear. Busca por tarjeta o celular.');return;}
const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});
if(generation!==cameraGeneration||location.hash!=='#empleado'){stream.getTracks().forEach(track=>track.stop());return;}camera=stream;document.querySelector('#scanner-shell')?.classList.add('is-scanning');
const video=document.querySelector('#video'),status=document.querySelector('#scan-status'),canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});
video.hidden=false;video.srcObject=camera;document.querySelector('#stop-scan').hidden=false;status.hidden=false;status.textContent='Apunta la cámara al código QR del cliente.';await video.play();if(button)button.textContent='Cámara activa';
const decodeWithJs=()=>{if(typeof window.jsQR!=='function'||video.readyState<2||!video.videoWidth)return'';const scale=Math.min(1,900/video.videoWidth),width=Math.max(1,Math.round(video.videoWidth*scale)),height=Math.max(1,Math.round(video.videoHeight*scale));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}context.drawImage(video,0,0,width,height);const frame=context.getImageData(0,0,width,height);return window.jsQR(frame.data,width,height,{inversionAttempts:'attemptBoth'})?.data||'';};
const scan=async()=>{if(!camera||generation!==cameraGeneration)return;let value='';if(detector){const results=await detector.detect(video).catch(()=>[]);value=results[0]?.rawValue||'';}if(generation!==cameraGeneration)return;if(!value)value=decodeWithJs();if(value){status.textContent='Código detectado. Buscando tarjeta…';stopCamera();await findCard(value);return;}scanTimer=setTimeout(scan,300);};
scan();
}catch{stopCamera();toast('No se pudo abrir la cámara. Revisa sus permisos.');}}
